type PersistedStateStorage = "localStorage" | "sessionStorage";

export function usePersistedState<T>(
  key: string,
  defaultValue: T,
  storageType: PersistedStateStorage = "localStorage"
): [T, (value: T) => void] {
  //in ssr, window doesn't exist, just use default
  const storage =
    typeof window !== "undefined" ? window[storageType] : undefined;
  const saved = storage?.getItem(key) ?? null;
  const [_state, _setState] = useState<T>(
    saved !== null ? JSON.parse(saved) : defaultValue
  );
  const setState = useCallback(
    (value: T) => {
      if (value === undefined) {
        console.warn(`${key} can't be stored as undefined, casting to null.`);
      }
      const v = value === undefined ? null : value;
      window[storageType].setItem(key, JSON.stringify(v));
      _setState(value);
    },
    [key, storageType]
  );
  return [_state, setState];
}

export function useSessionStorage<T>(
  key: string,
  defaultValue: T
): [T | undefined, (value: T) => void, () => void] {
  const [_state, setState] = usePersistedState<T | undefined>(
    key,
    defaultValue,
    "sessionStorage"
  );
  const clearState = useCallback(() => {
    window.sessionStorage.removeItem(key);
    setState(undefined);
  }, [key, setState]);
  return [_state, setState, clearState];
}

